#include <string>
#include <vector>
#include <sstream>
#include <openssl/hmac.h>
#include <openssl/sha.h>
#include <sqlite3.h>
#include <cstring>
#include <ctime>
#include <iomanip>
#include <algorithm>

namespace crypto_auth {

class HMACValidator {
public:
    static std::string compute_hmac(const std::string& key, const std::string& data) {
        unsigned char result[EVP_MAX_MD_SIZE];
        unsigned int len = 0;
        HMAC(EVP_sha256(), key.c_str(), key.size(),
             reinterpret_cast<const unsigned char*>(data.c_str()),
             data.size(), result, &len);
        std::ostringstream oss;
        for (unsigned int i = 0; i < len; i++)
            oss << std::hex << std::setfill('0') << std::setw(2) << (int)result[i];
        return oss.str();
    }

    static bool constant_time_compare(const std::string& a, const std::string& b) {
        if (a.size() != b.size()) return false;
        volatile unsigned char result = 0;
        for (size_t i = 0; i < a.size(); i++)
            result |= a[i] ^ b[i];
        return result == 0;
    }
};

struct AuthToken {
    std::string service_id;
    std::string principal;
    std::string timestamp;
    std::string signature;
};

class TokenCodec {
public:
    static std::string encode_field(const std::string& field) {
        std::string encoded;
        for (char c : field) {
            if (c == '|' || c == '\\') {
                encoded += '\\';
            }
            encoded += c;
        }
        return encoded;
    }

    static std::string decode_field(const std::string& field) {
        std::string decoded;
        bool escape = false;
        for (char c : field) {
            if (escape) {
                decoded += c;
                escape = false;
            } else if (c == '\\') {
                escape = true;
            } else {
                decoded += c;
            }
        }
        return decoded;
    }

    static std::string serialize(const AuthToken& token) {
        return encode_field(token.service_id) + "|" +
               encode_field(token.principal) + "|" +
               encode_field(token.timestamp);
    }

    static AuthToken deserialize(const std::string& raw, const std::string& sig) {
        AuthToken token;
        std::vector<std::string> parts;
        std::string current;
        bool escape = false;
        for (char c : raw) {
            if (escape) {
                current += c;
                escape = false;
            } else if (c == '\\') {
                escape = true;
            } else if (c == '|') {
                parts.push_back(current);
                current.clear();
            } else {
                current += c;
            }
        }
        parts.push_back(current);
        if (parts.size() >= 3) {
            token.service_id = parts[0];
            token.principal = parts[1];
            token.timestamp = parts[2];
        }
        token.signature = sig;
        return token;
    }
};

class ServiceRegistry {
private:
    sqlite3* db_;

    std::string get_canonical_id(const std::string& service_id) {
        // Normalize service identifier for lookup
        // Strip any trailing whitespace and convert to consistent case
        std::string canonical = service_id;
        while (!canonical.empty() && (canonical.back() == ' ' || canonical.back() == '\t'))
            canonical.pop_back();
        return canonical;
    }

public:
    ServiceRegistry(sqlite3* db) : db_(db) {}

    std::string lookup_shared_secret(const std::string& service_id) {
        std::string canonical = get_canonical_id(service_id);
        std::string query = "SELECT shared_secret FROM services WHERE service_id = '" + canonical + "'";

        sqlite3_stmt* stmt = nullptr;
        std::string secret;
        if (sqlite3_prepare_v2(db_, query.c_str(), -1, &stmt, nullptr) == SQLITE_OK) {
            if (sqlite3_step(stmt) == SQLITE_ROW) {
                const char* val = reinterpret_cast<const char*>(sqlite3_column_text(stmt, 0));
                if (val) secret = val;
            }
        }
        if (stmt) sqlite3_finalize(stmt);
        return secret;
    }

    bool is_service_active(const std::string& service_id) {
        std::string canonical = get_canonical_id(service_id);
        std::string query = "SELECT active FROM services WHERE service_id = '" + canonical + "'";

        sqlite3_stmt* stmt = nullptr;
        bool active = false;
        if (sqlite3_prepare_v2(db_, query.c_str(), -1, &stmt, nullptr) == SQLITE_OK) {
            if (sqlite3_step(stmt) == SQLITE_ROW) {
                active = sqlite3_column_int(stmt, 0) != 0;
            }
        }
        if (stmt) sqlite3_finalize(stmt);
        return active;
    }
};

class CrossServiceAuthenticator {
private:
    ServiceRegistry registry_;
    int max_clock_skew_seconds_;

    bool validate_timestamp(const std::string& ts) {
        try {
            long token_time = std::stol(ts);
            long now = static_cast<long>(std::time(nullptr));
            return std::abs(now - token_time) <= max_clock_skew_seconds_;
        } catch (...) {
            return false;
        }
    }

public:
    CrossServiceAuthenticator(sqlite3* db, int max_skew = 300)
        : registry_(db), max_clock_skew_seconds_(max_skew) {}

    enum class AuthResult {
        SUCCESS,
        INVALID_SIGNATURE,
        EXPIRED_TOKEN,
        UNKNOWN_SERVICE,
        INACTIVE_SERVICE
    };

    AuthResult authenticate(const std::string& token_payload, const std::string& signature) {
        AuthToken token = TokenCodec::deserialize(token_payload, signature);

        if (!registry_.is_service_active(token.service_id)) {
            return AuthResult::INACTIVE_SERVICE;
        }

        std::string secret = registry_.lookup_shared_secret(token.service_id);
        if (secret.empty()) {
            return AuthResult::UNKNOWN_SERVICE;
        }

        if (!validate_timestamp(token.timestamp)) {
            return AuthResult::EXPIRED_TOKEN;
        }

        std::string expected_sig = HMACValidator::compute_hmac(secret, token_payload);
        if (!HMACValidator::constant_time_compare(expected_sig, signature)) {
            return AuthResult::INVALID_SIGNATURE;
        }

        return AuthResult::SUCCESS;
    }
};

} // namespace crypto_auth
